import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in), 1 << 16));
        in.nextToken(); int N = (int) in.nval;
        in.nextToken(); int K = (int) in.nval;
        in.nextToken(); long T = (long) in.nval;

        int[] P = new int[N + 1];
        for (int i = 1; i <= N; i++) { in.nextToken(); P[i] = (int) in.nval; }

        int[] g = new int[K];
        int idx = 0;
        for (int i = 1; i <= N; i++) { in.nextToken(); if ((int) in.nval == 1) g[idx++] = i; }
        // g[0..K-1] = posições iniciais do grupo, em ordem crescente.
        // Custo mínimo de trocas para chegar ao conjunto de posições finais f1<f2<...<fK
        // é soma |g_i - f_i| (matching monótono), pois trocas entre dois membros do grupo
        // não alteram o conjunto de posições ocupadas.

        int V = 9 * K;
        final int INF = 1 << 29;

        int[][] prev = new int[N + 1][V + 1];
        int[][] cur = new int[N + 1][V + 1];
        for (int j = 0; j <= N; j++) {
            int[] pj = prev[j], cj = cur[j];
            for (int v = 0; v <= V; v++) { pj[v] = INF; cj[v] = INF; }
            pj[0] = 0; // camada 0: 0 membros, custo 0, valor 0
        }

        // dp[i][j][v] = custo mínimo atribuindo os primeiros i membros a posições
        // distintas todas <= j, com valor total exatamente v.
        // transição: dp[i][j][v] = min(dp[i][j-1][v], dp[i-1][j-1][v-P[j]] + |g_i - j|)
        for (int i = 1; i <= K; i++) {
            int gi = g[i - 1];
            int maxV = 9 * i;
            for (int v = 0; v <= maxV; v++) cur[0][v] = INF;
            for (int j = 1; j <= N; j++) {
                int pj = P[j];
                int delta = gi > j ? gi - j : j - gi;
                int[] curj = cur[j], curj1 = cur[j - 1], prevj1 = prev[j - 1];
                for (int v = maxV; v >= 0; v--) {
                    int best = curj1[v];
                    int vp = v - pj;
                    if (vp >= 0) {
                        int c = prevj1[vp];
                        if (c < INF) {
                            c += delta;
                            if (c < best) best = c;
                        }
                    }
                    curj[v] = best;
                }
            }
            int[][] t = prev; prev = cur; cur = t;
        }

        int ans = 0;
        int[] fin = prev[N];
        for (int v = V; v >= 0; v--) {
            if (fin[v] < INF && fin[v] <= T) { ans = v; break; }
        }
        System.out.println(ans);
    }
}
